SELECT [Поставки угля].электростанция, [Поставки угля].numb, [Поставки угля].[жд ст получ], [Поставки угля].уголь, [Поставки угля].[жд станция отпр], [Поставки угля].расстояние, (select средн from [И1_Поясные_расстояния] where (расстояние>=нач and расстояние<=кон)) AS L, (select Кп3т2 from Кп3т2 where расстояние>=[нач] and расстояние<=[кон]) AS k1, Round(IIf([L]<=160,1.23,IIf([L]<3000,1.041-0.00006*[L]+31/[L],0.87)),2) AS KL, 2132+(8.116+0.0338*70)*[KL]*[L] AS И1, 1126+1.304*[L]*0.87 AS В4, [и1]*[k1]+[в4] AS Т1, (2132+(8.116+0.0338*70)*0.87*3550)*0.63+1126+1.304*0.87*3550 AS Т3500, (IIf([расстояние]<3500,[Т1],[Т3500]+0.333*([Т1]-[Т3500])))/70 AS T
FROM [Поставки угля];
